figures.asymptoteSource:
// Slope read as rise over run between two points.
// Two-argument size call fixes the output box, so the declared 4/3 is exact.
size(320,240);
pair A=(0,0), B=(4,3);
draw((-0.5,-0.4)--(4.9,3.67));
draw(A--(4,0));
draw((4,0)--B);
dot(A, black+2.5pt);
dot((4,0), black+2.5pt);
dot(B, black+2.5pt);
label("$A=(0,0)$",A,SW);
label("$B=(4,3)$",B,NE);
label("run $=4$",(2,0),S);
label("rise $=3$",(4.15,1.5),E);
label("$m=\frac{3}{4}$",(2,1.6),NW);

// Two lines meeting at the solution of a system.
// Two-argument size call fixes the output box, so the declared 4/3 is exact.
size(320,240);
pair S=(2,3);
draw((-1.2,0.53)--(3.2,4.27));
draw((-1.2,4.27)--(3.2,0.53));
draw((-1.2,0)--(4.3,0),Arrow);
draw((0,-1.2)--(0,4.8),Arrow);
label("$x$",(4.4,0),E);
label("$y$",(0,4.85),N);
dot(S, black+3.5pt);
label("$S$",S,NE);
label("$x=2$",(2,0.35),S);
label("$y=3$",(-0.3,3),E);
label("the unknowns are the axis values where the lines cross",(1.6,-0.95),S);
